package com.atlashub.pay.txquery.domain.entities;

import com.atlashub.pay.txquery.domain.valueobject.*;import com.atlashub.shared.application.security.ApiEnvironment;import com.atlashub.shared.domain.valueobject.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.ZonedDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class TransactionRecordTest {@Test void createsAndAdvancesLifecycle(){var record=TransactionRecord.create(1L,2L,ApiEnvironment.TEST,TransactionType.CHARGE,TransactionStatus.PENDING,Money.of(new BigDecimal("100"),CurrencyCode.NGN),"CARD","PAYSTACK","ref","COMMERCE_CHECKOUT","order-1","CUSTOMER","customer-1",null,null,null,"Sale",Map.of(),ZonedDateTime.now());assertEquals(TransactionStatus.PENDING,record.getStatus());record.updateStatus(TransactionStatus.SUCCESSFUL,ZonedDateTime.now(),null);assertEquals(TransactionStatus.SUCCESSFUL,record.getStatus());assertNotNull(record.getCompletedAt());}@Test void attachesAccountEntries(){var record=TransactionRecord.create(1L,2L,ApiEnvironment.TEST,TransactionType.LEDGER_POST,TransactionStatus.SUCCESSFUL,Money.of(BigDecimal.TEN,CurrencyCode.NGN),"INTERNAL","INTERNAL","r","SYSTEM","r",null,null,null,null,null,null,Map.of(),ZonedDateTime.now());record.attachAccountEntries(List.of(new TransactionAccountEntry(3L,1L,4L,"OPERATING","Operating","CREDIT",TransactionDirection.INCOMING,Money.of(BigDecimal.TEN,CurrencyCode.NGN))));assertEquals(TransactionDirection.INCOMING,record.primaryDirection());}}
